+									: undefined
+							}
+							label="Changes"
+							onToggle={() => setChangesOpen((open) => !open)}
+							open={changesOpen}
+						>
+							{changes.map((file) => (
+								<ChangeRow
+									actions={
+										<>
+											<RowAction
