+												label={`Discard changes to ${file.path}`}
+												onClick={() => onRequestDiscard([file])}
+											>
+												<Undo2 className="size-3" />
+											</RowAction>
+											<RowAction
+												disabled={busy}
+												label={`Stage ${file.path}`}
+												onClick={() =>
+													void onAction({ type: "stage", paths: [file.path] })
+												}
+											>
+												<Plus className="size-3" />
